class Solution:
    def validNumber(self, s: str) -> bool:
        if not s or any(c not in "+-.eE0123456789" for c in s):
            return False
        try:
            float(s)
        except ValueError:
            return False
        t = s.lower()
        return "inf" not in t and "nan" not in t

